11	      --circle-hue: #8ec5ff;
12	      --circle-core: #4a7dd9;
13	      --circle-shadow: #1f3a75;
14	      --cycle: 2.5s;
15	    }
16	    * {
17	      margin: 0;
18	      padding: 0;
19	      box-sizing: border-box;
20	    }
21	    body {
22	      width: 100vw;
23	      height: 100vh;
24	      height: 100dvh;
25	      display: flex;
26	      flex-direction: column;
27	      justify-content: center;
28	      align-items: center;
29	      gap: 24px;
30	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
31	      overflow: hidden;
32	    }
33	    svg {
34	      width: min(400px, 80vmin);
35	      height: min(400px, 80vmin);
36	      overflow: visible;
37	      cursor: pointer;
38	      user-select: none;
39	      -webkit-tap-highlight-color: transparent;
40	      transition: filter 0.3s ease;
41	    }
42	    svg:hover {
43	      filter: brightness(1.08);
44	    }
45	    svg:focus-visible {
46	      outline: 2px solid var(--circle-hue);
47	      outline-offset: 8px;
48	      border-radius: 50%;
49	    }
50	    .ambient {
51	      fill: var(--circle-hue);
52	      opacity: 0.12;
53	      filter: blur(30px);
54	      animation: breathe var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
55	      transform-origin: 200px 200px;
56	      will-change: transform, opacity;
57	    }
58	    .core {
59	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
60	      transform-origin: 200px 200px;
61	      filter: url(#glow);
62	      will-change: transform, opacity;
63	    }
64	    .highlight {
65	      fill: url(#highlightGradient);
66	      transform-origin: 200px 200px;
67	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
68	      pointer-events: none;
69	      will-change: transform, opacity;
70	    }
71	    .ring {
72	      fill: none;
73	      stroke: var(--circle-hue);
74	      stroke-width: 2.5;
75	      transform-origin: 200px 200px;
76	      animation: ripple var(--cycle) cubic-bezier(0.2, 0.6, 0.4, 1) infinite;
77	      will-change: transform, opacity, stroke-width;
78	    }
79	    .ring--delay-1 {
80	      animation-delay: calc(var(--cycle) / 3);
81	    }
82	    .ring--delay-2 {
83	      animation-delay: calc(var(--cycle) / 3 * 2);
84	    }
85	    @keyframes pulse {
86	      0%, 100% {
87	        transform: scale(1);
88	        opacity: 0.9;
89	      }
90	      50% {
91	        transform: scale(1.05);
92	        opacity: 1;
93	      }
94	    }
95	    @keyframes breathe {
96	      0%, 100% {
97	        transform: scale(0.95);
98	        opacity: 0.1;
99	      }
100	      50% {
101	        transform: scale(1.1);
102	        opacity: 0.18;
103	      }
104	    }
105	    @keyframes ripple {
106	      0% {
107	        transform: scale(1);
108	        opacity: 0.6;
109	        stroke-width: 2.5;
110	      }
111	      100% {
112	        transform: scale(1.35);
113	        opacity: 0;
114	        stroke-width: 0.5;
115	      }
116	    }
117	    body.paused .core,
118	    body.paused .ring,
119	    body.paused .ambient,
120	    body.paused .highlight {
121	      animation-play-state: paused;
122	    }
123	    .speed-label {
124	      color: var(--circle-hue);
125	      font-family: system-ui, sans-serif;
126	      font-size: 0.85rem;
127	      letter-spacing: 0.05em;
128	      opacity: 0.85;
129	      user-select: none;
130	      text-align: center;
131	    }
132	    .hint {
133	      display: block;
134	      margin-top: 4px;
135	      font-size: 0.7rem;
136	      opacity: 0.85;
137	    }
138	    .controls {
139	      display: flex;
140	      align-items: center;
141	      gap: 12px;
142	      max-width: min(320px, 90vw);
143	    }
144	    .pause-btn {
145	      display: inline-flex;
146	      align-items: center;
147	      justify-content: center;
148	      width: 36px;
149	      height: 36px;
150	      padding: 0;
151	      border-radius: 50%;
152	      border: 1px solid var(--circle-hue);
153	      background: transparent;
154	      color: var(--circle-hue);
155	      cursor: pointer;
156	      transition: background 0.2s ease;
157	    }
158	    .pause-btn:hover {
159	      background: rgba(142, 197, 255, 0.15);
160	    }
161	    .pause-btn:focus-visible {
162	      outline: 2px solid var(--circle-hue);
163	      outline-offset: 2px;
164	    }
165	    .pause-btn svg {
166	      width: 14px;
167	      height: 14px;
168	    }
169	  </style>
170	</head>
171	<body>
172	  <svg id="ae683f770" viewBox="0 0 400 400" role="button" tabindex="0" aria-label="Pulsing blue circle animation. Click or press Enter to change pulse speed." aria-describedby="speedText">
173	    <title>Pulsing blue circle animation</title>
174	    <defs>
175	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
176	        <stop offset="0%" stop-color="#8ec5ff"/>
177	        <stop offset="55%" stop-color="#4a7dd9"/>
178	        <stop offset="100%" stop-color="#1f3a75"/>
179	      </radialGradient>
180	      <radialGradient id="highlightGradient" cx="32%" cy="28%" r="22%">
181	        <stop offset="0%" stop-color="#ffffff" stop-opacity="0.55"/>
182	        <stop offset="100%" stop-color="#ffffff" stop-opacity="0"/>
183	      </radialGradient>
184	      <filter id="glow" x="-80%" y="-80%" width="260%" height="260%">
185	        <feGaussianBlur in="SourceGraphic" stdDeviation="10" result="blur"/>
186	        <feColorMatrix in="blur" type="matrix"
187	          values="0 0 0 0 0.55  0 0 0 0 0.77  0 0 0 0 1  0 0 0 0.9 0" result="tintedBlur"/>
188	        <feMerge>
189	          <feMergeNode in="tintedBlur"/>
190	          <feMergeNode in="SourceGraphic"/>
191	        </feMerge>
192	      </filter>
193	    </defs>
194	    <circle class="ambient" cx="200" cy="200" r="160"/>
195	    <circle class="ring" cx="200" cy="200" r="140"/>
196	    <circle class="ring ring--delay-1" cx="200" cy="200" r="140"/>
197	    <circle class="ring ring--delay-2" cx="200" cy="200" r="140"/>
198	    <circle class="core" cx="200" cy="200" r="140" fill="url(#circleGradient)"/>
199	    <circle class="highlight" cx="200" cy="200" r="140"/>
200	  </svg>
201	  <div class="controls">
202	    <button type="button" class="pause-btn" id="pauseBtn" aria-pressed="false" aria-label="Pause animation">
203	      <svg id="pauseIcon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
204	        <path d="M6 4h4v16H6zM14 4h4v16h-4z"/>
205	      </svg>
206	    </button>
207	    <p class="speed-label" id="speedLabel" aria-live="polite">
208	      <span id="speedText">Normal speed</span>
209	      <span class="hint">Click circle to change speed</span>
210	    </p>
211	  </div>
212	  <script>
213	    const svg = document.getElementById('ae683f770');
214	    const speedText = document.getElementById('speedText');
215	    const pauseBtn = document.getElementById('pauseBtn');
216	    const pauseIcon = document.getElementById('pauseIcon');
217	    const PLAY_ICON = '<path d="M8 5l11 7-11 7z"/>';
218	    const PAUSE_ICON = '<path d="M6 4h4v16H6zM14 4h4v16h-4z"/>';
219	    const speeds = [
220	      { value: '2.5s', name: 'Normal speed' },
221	      { value: '1.2s', name: 'Fast speed' },
222	      { value: '4.5s', name: 'Slow speed' },
223	    ];
224	    let speedIndex = 0;
225	    const reducedMotionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
226	    let manuallyPaused = reducedMotionQuery.matches;
227	
228	    function updateLabels() {
229	      const { name } = speeds[speedIndex];
230	      speedText.textContent = manuallyPaused ? `${name} (paused)` : name;
231	    }
232	
233	    function cycleSpeed() {
234	      speedIndex = (speedIndex + 1) % speeds.length;
235	      const { value } = speeds[speedIndex];
236	      svg.style.setProperty('--cycle', value);
237	      // Restart animations from the beginning so the new speed feels immediate
238	      // instead of jumping mid-cycle.
239	      document.querySelectorAll('.core, .ring, .ambient, .highlight').forEach((el) => {
240	        el.style.animation = 'none';
241	        void el.offsetWidth;
242	        el.style.animation = '';
243	      });
244	      updateLabels();
245	    }
246	
247	    function applyPauseState() {
248	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
249	      pauseBtn.setAttribute('aria-pressed', String(manuallyPaused));
250	      pauseBtn.setAttribute('aria-label', manuallyPaused ? 'Resume animation' : 'Pause animation');
251	      pauseIcon.innerHTML = manuallyPaused ? PLAY_ICON : PAUSE_ICON;
252	      updateLabels();
253	    }
254	
255	    function togglePause() {
256	      manuallyPaused = !manuallyPaused;
257	      applyPauseState();
258	    }
259	
260	    svg.addEventListener('click', cycleSpeed);
261	    svg.addEventListener('keydown', (e) => {
262	      if (e.key === 'Enter' || e.key === ' ') {
263	        e.preventDefault();
264	        cycleSpeed();
265	      }
266	    });
267	
268	    pauseBtn.addEventListener('click', togglePause);
269	
270	    document.addEventListener('visibilitychange', () => {
271	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
272	    });
273	
274	    reducedMotionQuery.addEventListener('change', (e) => {
275	      manuallyPaused = e.matches;
276	      applyPauseState();
277	    });
278	
279	    applyPauseState();
280	  </script>
281	</body>
282	</html>
