232	  <script>
233	    const circleBtn = document.getElementById('circleBtn');
234	    const speedText = document.getElementById('speedText');
235	    const pauseBtn = document.getElementById('pauseBtn');
236	    const pauseIcon = document.getElementById('pauseIcon');
237	    const PLAY_ICON = '<path d="M8 5l11 7-11 7z"/>';
238	    const PAUSE_ICON = '<path d="M6 4h4v16H6zM14 4h4v16h-4z"/>';
239	    const speeds = [
240	      { value: '2.5s', name: 'Normal speed' },
241	      { value: '1.2s', name: 'Fast speed' },
242	      { value: '4.5s', name: 'Slow speed' },
243	    ];
244	    let speedIndex = 0;
245	    const reducedMotionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
246	    let manuallyPaused = reducedMotionQuery.matches;
247	
248	    function updateLabels() {
249	      const { name } = speeds[speedIndex];
250	      speedText.textContent = manuallyPaused ? `${name} (paused)` : name;
251	    }
252	
253	    function cycleSpeed() {
254	      speedIndex = (speedIndex + 1) % speeds.length;
255	      const { value } = speeds[speedIndex];
256	      circleBtn.style.setProperty('--cycle', value);
257	      // Restart animations from the beginning so the new speed feels immediate
258	      // instead of jumping mid-cycle.
259	      document.querySelectorAll('.core, .ring, .ambient, .highlight').forEach((el) => {
260	        el.style.animation = 'none';
261	        void el.offsetWidth;
262	        el.style.animation = '';
263	      });
264	      updateLabels();
265	    }
266	
267	    function applyPauseState() {
268	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
269	      pauseBtn.setAttribute('aria-pressed', String(manuallyPaused));
270	      pauseBtn.setAttribute('aria-label', manuallyPaused ? 'Resume animation' : 'Pause animation');
271	      pauseIcon.innerHTML = manuallyPaused ? PLAY_ICON : PAUSE_ICON;
272	      updateLabels();
273	    }
274	
275	    function togglePause() {
276	      manuallyPaused = !manuallyPaused;
277	      applyPauseState();
278	    }
279	
280	    circleBtn.addEventListener('click', cycleSpeed);
281	    pauseBtn.addEventListener('click', togglePause);
282	
283	    document.addEventListener('visibilitychange', () => {
284	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
285	    });
286	
287	    reducedMotionQuery.addEventListener('change', (e) => {
288	      manuallyPaused = e.matches;
289	      applyPauseState();
290	    });
291	
292	    applyPauseState();
293	  </script>
